) AS (
  VALUES 
    (115::BIGINT, 'El profe es supér cómico y hacía las clases muy interesantes. Honestamente entregue las cosas a tiempo y el curso se pasa solo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2026-08-06T00:00:00+00:00'::TIMESTAMPTZ, '8ad7cbfb195eb88cf05e571b94ab73ba8872dfc0e57729578740e40ca923ce61'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Hablar paja el curso. Meneses el goat'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2026-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'a18a133cc07e6b025cc5c61b7b3882edf8b7ba870f73084b1b1c10791aeded3d'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'El profesor es peculiar sin duda alguna, aveces se desvia del tema y termina hablando de otra cosa, pero es muy buen profe. Si llevas el curso con el no te vas a quedar, lo vas a pasar con 100 y no es matado. El profe entiende que su materia no es para quedar estudiantes. Es divertido y buena nota.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Da crédito extra']::TEXT[], '2026-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'c2d72103514e23a8a5e61772aa4bf2db1b0e0e7d3533bb20fce77b00b7eeb750'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-04-14T00:00:00+00:00'::TIMESTAMPTZ, 'a5540f8633e6d765170c19ff5968fd0384b7ac2a415a3cccaf69820071e45ebb'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Legalmente la clase es demasiado interesante, el profe es muy bueno y tiene mucho que decir, opinar y contar, es una pena que la gente no participe, opine y discuta todo lo que podría, porque realmente se presta mucho para aprender y compartir ideas o debatirlas, además se hace más sencillo así'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2026-04-04T00:00:00+00:00'::TIMESTAMPTZ, 'fe2ad5bbd52e14d816e989cf94be853056b95b2e9ef896a4241daba1b70cb319'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Pocos exámenes']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'fbc2d54b88c1061616a0cd9dcbb3de806457f8e2df8dd637613ba06e4a49d2e3'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Super gracioso, es imposible dormirse la clase es básicamente dar tips para pasar el Tec y contarnos sobre temas de política en el país y afuera de forma bastante interesante y entretenida. Las tareas son muy pocas y super fáciles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '82e5aa86dbe0199ec564931f0dbe3a6b8ccde2d136919990e91c89f15c151bd5'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Es muy buen profe, ayuda siempre que puede. Pero si lleva muchos créditos no lo recomiendo, los trabajos son largos y hay que dedicarle tiempo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2025-06-21T00:00:00+00:00'::TIMESTAMPTZ, '21c1f14093114215126ea0b0d813c5b40fc12c0cb51ac3def4dc2a9b3b77b7db'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Muy fácil (no da verano), deja 2 ensayos de lecturas, 1 trabajo grupal, 1 presentación individual sencilla, y el resto es participación. Si necesita más tiempo para entregar alguna tarea, pídaselo y él gustoso se lo dará. Siga las indicaciones de las guías. Le gusta hablar de política y noticias.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, '38ed5de5a8c459a1cddae3e75a359a27b7668b50b915a05de87144f8c07b1695'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Excelente profesor, muy gracioso. Realmente el curso se pasa solo, los exámenes se basan en preguntas donde usted debe dar su opinión de algunas lecturas cortas que él facilita. Ampliamente recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-08-11T00:00:00+00:00'::TIMESTAMPTZ, '95ba553dbc8f7a036af5ad7ef90f3d51fad7094e088a36f903a18d98b16bf436'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'El profe es muy buena nota. Hace la clase divertida y no busca complicarla. El curso en sí es fácil de pasar y el profe da puntos extra antes de los examenes con un formulario electrónico.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'cecc684e185d67d387e1c4ea5278ff6d27e89b705358ffe294c075d6c6ed377a'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Un profesor muy bueno, su materia se hace bastante ligera y casi no deja trabajos. Deja bastantes lecturas pero no es necesario leerlas para la clase ya que el las comenta. Los exámenes son para la casa y son muy de opinión propia. Ultra recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Respetado por los estudiantes']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '816519514939a97387130e92c890d046be961996cba4651f5ba5b3067404e37a'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Es super buena gente, trata a los estudiantes con mucho respeto y fomenta la participación en clases, solo quiere que entre el grupo haya conversaciones interesantes. Fue el curso al que me iba a despejar porque realmente era muy relajante e interesante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-12-21T00:00:00+00:00'::TIMESTAMPTZ, '3f66a0b1c5dd62ac7bb7327c3713709a9583ff9d2c6c872260e142a477f48a4d'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Demasiado buen profesor, hace la clase muy divertida con sus comentarios y se aprende demasiado de historia y sociología. Deja 2 lecturas largas pero muy interesantes. Vale demasiado la pena, matricule con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-14T00:00:00+00:00'::TIMESTAMPTZ, '7ccea14afaa685c7ad169089394ec349e99fca273800def1df86422e5e16a689'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Él hace que un curso que se considera aburrido sea entretenido, de verdad se preocupa porque uno aprenda lo que es importante y que uno de su opinión no que vaya a repetir lo que escucha. Súper buen profe, matricule con él no se va a arrepentir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'd6cc584e666c58bf019cf2b5cb65215bc8c97476c518010db859a2ccf1d55571'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'El profe es muy chistoso y vuelva una clase que mucha gente considera aburrida en algo entretenido, vale completamente la pena matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, '8d9ccafc1a9180f72ca81d91cfb47976743ba04814a900f36f2b0a7009114092'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Un profe realmente distinto, se preocupa por hacer un curso en el que estudiante aprenda algo para la vida. Es muy cómico y los trabajos son fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b1cd488f32ab519a5a685986fecd99d882ec0dc8e9cc35e6c1eb293a350638f2'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Es el profe con el que tiene que matricular. Saca lo mejor del curso y se esfuerza para hacerlo entretenido. Diseña todo el curso para que no lleve mucho tiempo y su objetivo es darle la mejor nota. Es súper buena gente y cómico'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'd6ec85a65e31cf0834140c974a9aa10b9954f9ae60ae7a470449f6704dd6415f'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'El curso en si es un bostezo lit, pero el profe lo hace menos aburrido, es como un señor todo metalero pero cómico. Deja lecturas que en la clase las comenta, si le quieren caer mejor participen en clase sino se pone sad. Siempre pasa una lista de asistencia. SUPER RECOMENDADO'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '3fd807434d3f87e79f0687268b725c40415d667863c085188c7e216609605eba'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'es gracioso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-09T00:00:00+00:00'::TIMESTAMPTZ, '7154d9994748b64d75b8d1a341edcfd4aa1e9238f11d826d475921d1c4f9ad43'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Básicamente solo deja dos ensayos que se sacan super rápido, una exposición individual y una grupal. La asistencia es muy importante y el profe siempre responde rápido ante alguna duda que se tenga.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'b6433af3713a49ceb9b09b4f6af8d21fdedc46d4c144caf71d94168ceb591201'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Con este profesor el curso es un puro chingue. La materia es aburridísima, pero el profe mete uno que otro chiste para mantener a la clase interesada. Las evaluaciones son dos ensayos que en dos horas los tienes. El curso se pasa solo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-27T00:00:00+00:00'::TIMESTAMPTZ, '5f5c8a558af6daf5f4c544cf6fc37f80feb6b790b3eeeb8ab3bfb101705ed81c'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Da crédito extra']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '7dd5b2dc2c106d03d058a4c3b35ee9bf433bb2b0f849a4862f656468d8d889f6'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Es un excelente profesor. Entiende que el curso es de solamente un crédito, entonces hace las clases muy llevaderas y deja muy pocos trabajos, los cuales califica de manera suave. Recomendado sin dudarlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '98d3fe9012a3ac69a204d49139cc0184416000360407a2f7d249de59b64d2c59'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'De los mejores profes que hay en el TEC. Hace que el curso no sea tan aburrido de lo que ya es. Todos los aspectos de evaluación están dentro del programa del curso y también deja lecturas semanales que liego en clase explica muy bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, '1f00e69f738f77ba35b13dabc4b398355687ddc7b3ad461445b77d324ad03d0f'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Un profe diferente a lo que uno se encuentra en el TEC. Super buena nota y siempre es muy bueno con los estudiantes, da tiempo de hacer las cosas. Hay lecturas semanales pero el curso se pasa facilísimo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'a32276bdff97cd808fdd5ac46dfaddbc793856c6a46a2ad73b444ac5cdc07ee8'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'El profe es graciosísimo. Absolutamente todos los trabajos que se van a realizar durante el semestre están en un cronograma ordenado en la página. Deja lecturas semanales que explica en clase, pero no son obligatorias. También le gusta que uno opine en clase, pero nada más. Un curso súper.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'f967879baec3374214b2e49aa7fdc3162b8771c2509a264c83a1a0635095cc6d'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Un excelente profesor, es un chancletudo mas de la UCR, pero es una teja, sabe demasiado y si te pones a hablar con él, te da cuerda para un buen rato sea el tema que sea, hace que la clase no sea aburrida y es super cómico, definitivamente si quiere disfrutar intro al bostezo, matricule con él!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-04-06T00:00:00+00:00'::TIMESTAMPTZ, '68e67864f761f2aafc49aba76c536daa10c0ddf2d4643b658674d20624a80023'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Hay que participar bastante porque le gusta dirigir las clases hablando de temas de interes de los estudiantes. Sabe bastante de lo que habla y es muy buena nota. Los trabajos son bastante fáciles y se pasa relajado. Siempre da retroalimentación cuando uno la pida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'd8e29ab6c6cd74a7b2ab5d22c52f4b08feda1859c39e7399abe3855439b822ab'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Es importante que participen en clase para que el profe no se decepcione, ya que le interesa mucho que los estudiantes interactúen con los temas que habla. Las clases son fáciles e interactivas, y nos pregunta sobre temas que hayan ocurrido últimamente para comentarlos en clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'f940794a0c08347105a0ca42885d365007b38947848fda45ee091252cf4fdd85'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'El mejor profesor que he tenido en el TEC. No hay nada malo que decir de él, es comprensivo con los estudiantes, es gracioso y explica bien la materia. Le gusta que los estudiantes participen mucho y se nota un poco desanimado si no lo hacen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, '8b39ee67e0c56f39805127e4543b663a2528273ab9a3a7988450228c1891572b'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Excelente curso, solo hay que exponer sobre algo actual, hacer unos trabajos en grupo y para ello revisar bien bien que pide y seguir las instrucciones y todo va a salir de tejita.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-11-12T00:00:00+00:00'::TIMESTAMPTZ, '8f24e7b0dfa99049657f05ee579fd8bd05f1aaa2f56b2531fd524c4f70dc1d05'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'La verdad este profe es excelente, me cayó increíble y es suuuper buena onda. Super de respetarse la verdad, el TEC necesita más profes así'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2021-11-12T00:00:00+00:00'::TIMESTAMPTZ, '1e8439c3d0f6da6ac4a7ce5dba0781ae29eb95baa01c416477f98e6e3466e295'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'El profe es un crack, las clases son dinámicas y para nada aburridas, si llevan este curso matriculen con él y no se van a arrepentir de lo bueno que es en la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-27T00:00:00+00:00'::TIMESTAMPTZ, '3bdaa7a72488b8a1237c13249c1e2c83c525bb24608bdcfc3a047393d754fcc6'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'El profe es una teja hace el curso bastante interesante y entretenido. Deja los examenes para la casa'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '5be7db8bf9b3ccfa5cc0ab39b18a40ca6c2890d83872b4f0c64ebd3d9f29f880'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'De los mejores profes que he tenido. Se interesa porque el estudiante aprenda y crezca de manera integral. Es muy justo, empático y gracioso. No duden en matricular con él, no se van a arrepentir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd9c105043a25ba55afdb7cfcf783644eaff59f86bc82c62e2260236f84e6fc54'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'El mejor profesor que he tenido al momento, atento porque sus estudiantes aprendan, todo es totalmente entendible, súper accesible, las clases hasta divertidas son.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-18T00:00:00+00:00'::TIMESTAMPTZ, '45005c3245e3853333117df031f6d8c2c76e6de65579b2c60217f746f5f4ce1d'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Excelente profesor, hace las clases muy interesantes, realmente se puede aprovechar el curso como un despeje del resto de cursos, así se conecta mejor con temas que se dejaron de lado desde el colegio. Se nota el esfuerzo por parte de él. Respecto a trabajos, es bastante sencillo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '6b4f392cffbb2f4df8f8fb0e3ff69a11c0d6a997b7db13b59a102df926409ab5'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Las clases son super entretenidas e interesantes el profe es muy buena nota y gracioso , califica suave, más que cualquier otra cosa le importa mucho que usted entienda, imposible quedarse, en este caso no aplica llamar al curso intro al bostezo porque nunca es aburrido ni cansado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-08T00:00:00+00:00'::TIMESTAMPTZ, 'b86ceda8fd9069ba59237308e45e2a8f033ead46392a18179d6c23bf4698c88f'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Excelente profesor para clases presenciales o virtuales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'fbac15e7ebed5cda5a5a199fa28a12f0cb000855fc92f02ed92719825017e7a4'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Excelente profe, siempre intenta ayudar y comprender al estudiante, no dude en llevar cursos con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, '84c9500591582ab30d5ae30e6da1af04f5cc3311c611aef9cdf72feba62333f6'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Es excelente profesor, su clase deja mucho aprendizaje, comprende las necesidades de los estudiantes y los exámenes son sobre temas que ya ha explicado durante la clase, se pasa prestando atención en clase y cumpliendo con lo que él pida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '9370dd34cbc8b6551f57d18f36db457096c80c19c59a8ac162079e2b2483e535'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'El profe es consciente de que este curso no es la prioridad de los estudiantes, por lo que deja tareas sencillas y que no demandan mucho tiempo. Hace la clase interesante ya que sabe de muchos temas, realmente se aprende mucho con él.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '25fad7d16655472a3d7a94394fd2dbe4b4e7132cc84e79392f7e1dfcc70017c7'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, '3f31acb58c2d84b68a2f958ccc73851ded3f5a9bf56cd513ac4861a681e1abb9'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Es muy buen profe, hace que la clase no sea tan aburrida, explica y deja los trabajos claros y brinda mucho apoyo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '13e97983a2433044ef3c10919a0c98e6978f11d23f49dd213190182971554313'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Profe muy pura vida, califica normal y hace que intro al bostezo no sea tan aburrida. Lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, 'cd1ce494e9a13cce1bc189b8cfc6370579f6ab3e5d1a12732eceebc7715de479'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2020-02-24T00:00:00+00:00'::TIMESTAMPTZ, '7e1f47e346d5ed9e2134a1e267ea7cec1896eb033a962dffeb1d912cf76741c2'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'El curso con él es súper fácil, si deja trabajos pero no son la gran cosa y las clases son interesantes'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'aab3170ad6d8b5414c897c4209bf686a5df02d2dbfc5a638abd95bae9bc7b491'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Las clases son muy interesantes y entretenidas. En clases se analiza lo que está pasando en el país y explica cosas importantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2019-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'e5850a357ca1b3dddb46f1591d43f8399eaf2e8593f386495c72c763f4a4712d'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'El curso con él es cero aburrido. Los exámenes son fáciles si usted le pone atención en clase, siempre pone una sección de puntos extra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'cd1df30ef297ad6b997d4b9a12029cb953603de3fdbcf6e48d813f70df834033'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Muy buen profesor. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '47fa0132fa914380dd99896cdc16b4ec428c2f748bcea555f9badc237c16e058'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Muy buen profesor, en clases se habla de lo que realmente importa y da mucha ayuda a los estudiantes'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2019-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'b22296cd42172dcf8f65906a8598b1f7f714c2b134a3bb60a7cd76bc864982c6'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Las clases no son para nada aburridas y siempre antes de empezar la clase suele hablar de temas actuales.Los exámenes son fáciles si usted le pone atención en clases'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '06e79e0d42bcf8a0d089edbad3bb529f3ebcdc15158aef2918c2c31bfdccd011'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Debería de ser un curso de esos bien aburridos, pero este profesor lo hace tuanis, se hablan de temas actuales inclusive. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c6786c781584bf0decbba93d9877f904120474364b1f65e5c5531680100156e2'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Básicamente lo que se ve en clases no es evaluado en los trabajos. La asistencia es obligatoria. Deja pocas evaluaciones y son muy fáciles (sobre todo deja ensayos de libros). Le gusta discutir en clase sobre temas actuales en el país. Es muy divertido y califica suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '337bdba7549b1594fbaa2d07a2382cd325b654d3849b9fec542c5bea1498800e'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '1713642e58a47e4870f8bb60291654c264479dd2d77dabe63f9b6d5964a76ad1'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Excelente profesor,cae muy bien, las clases no son tan aburridos y se aprende algo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'bd5039a1074bf2a212b4ff5a01fdc8b43446c7a100dcd156dda373d79f8bb2fb'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-13T00:00:00+00:00'::TIMESTAMPTZ, 'ac44a60118b93eddd059d947056a2dcc230ac47a80075cf8dfaf347c0217a86d'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, 'De los mejores profes que he tenido. Siempre habla temas interesantes de la actualidad del país y los temas de la clase los hace entretenidos. Para los trabajos tiene una lista de libros super buenos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-31T00:00:00+00:00'::TIMESTAMPTZ, '484b7f1406456143a228ce0bc1539cc646ed9d9f055ce05151bc0e5d0170dc7e'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Excelente profesor! Muy divertido. Hace que las clases sean entretenidas. Le gusta hablar sobre la situación del país, con críticas muy acertadas. No deja muchos trabajos. Sin duda, uno de los mejores profes que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-28T00:00:00+00:00'::TIMESTAMPTZ, '86b809bb6134a391f083e36b854252c14475a1e90039e4ca73d8cd2e796045dc'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'El mejor profe para este curso, se aprende, se pasa bien, y todos pasan facil. En mi grupo todos arriba de 85'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '5eba1d8ab5935d389dd2db4258d6e958982bcc1835d37c9f2064baf2efe6f3db'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Definitivamente se sale del molde. Intenta activamente que los estudiantes participen, no anda con palabras finas ni rodeos: las cosas como son. En el curso se aprende más de pensamiento crítico que de cualquier cosa que se intenta realmente enseñar, pero el profe es una buena opción a considerar'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'c11158c6a59b1f8964cfc3b1f155c410b6e2bf0c97f03673a83738718532fb60'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Excelente profesor. Uno de los mejores para hablar de política, con un buen sentido del humor. Las clases son amenas con él. Super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2017-07-28T00:00:00+00:00'::TIMESTAMPTZ, '7cd8c9c2fc0c5dd06c693dc6efcfe2800efac0556d9706146a50705157fc0fe4'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'A veces es un poco aburrida la clase, pero es un excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'fb0fe80bb5ddfe5c1153496be4d5cff197902a79f03621f9d64922f32fde8dbb'::TEXT, ARRAY[559]::BIGINT[]),
    (115::BIGINT, '¡El mejor profe del mundo! Hace las clases muy divertidas, y al inicio se empieza con una conversación del acontecer mundial.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Inspirador']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '46c884d97eca989609b0c63e616763193f8bba414443945e2cff5a20bc06d800'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Matricule sin pensarlo!.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '05f8687500833e9907b1f621affaaee73033cb707aa26a3ae7c18c0262d45c5e'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Excelente =)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'a9485bab43f2467472f44d8420857a0b1486b549724eaffb0ef6c5c256ff9c6f'::TEXT, ARRAY[1004]::BIGINT[]),
    (115::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'f5b1ff17071b1ad7227cd0bcaa9d4c6e5543dc87188253b9235aa32c336654bf'::TEXT, ARRAY[1004]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
